<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { Download, GitCompareArrows, Plus, ShieldCheck } from 'lucide-vue-next'
import TaskTabs from '../components/TaskTabs.vue'
import ExportFormatPicker from '../components/ExportFormatPicker.vue'
import Pager from '../components/Pager.vue'
import Modal from '../components/Modal.vue'
import DraftNotice from '../components/DraftNotice.vue'
import { useDraft } from '../drafts'
import { all, ApiError, api, dateTimeLabel, isProjectReadOnly, messageOf, notify, projectName, query, ui } from '../api'
import { builtinTemplate,type ExportFormat,type ExportJob,queuePrintExport,queueWordExport } from '../exports'
import { planningLabels,planningValue,type PlanComparison,type PlanVersion } from '../planning'
import type { Page,Project } from '../types'
const props=defineProps<{revision:number}>()
const emit=defineEmits<{changed:[]}>()
const project=ref(''),items=ref<PlanVersion[]>([]),detail=ref<PlanVersion>(),total=ref(0),offset=ref(0),loading=ref(false),error=ref(''),creating=ref(false),saving=ref(false),exporting=ref(false),comparing=ref(false),comparison=ref<PlanComparison>(),from=ref(''),to=ref('current')
const form=reactive({name:'',description:''}),limit=20,choices=ref<PlanVersion[]>([]),projectVersion=ref(0),planStale=ref(false)
const changeGroups=computed(()=>comparison.value?[{label:'新增',tasks:comparison.value.added},{label:'删除',tasks:comparison.value.removed}]:[])
const draft=useDraft(()=>`plan-versions:new:${project.value}`,form,()=>creating.value)
let request=0,detailRequest=0
const currentProject=computed(()=>ui.projects.find(p=>p.id===project.value))
function canLeave(){return !saving.value&&!exporting.value&&(!creating.value||draft.canLeave())}
async function load(){const seq=++request;loading.value=true;error.value='';if(!project.value){items.value=[];total.value=0;loading.value=false;return}try{const [page,versions]=await Promise.all([api<Page<PlanVersion>>(`/api/projects/${project.value}/plan-versions?${query({limit,offset:offset.value})}`),all<PlanVersion>(`/api/projects/${project.value}/plan-versions`)]);if(seq!==request)return;items.value=page.items;choices.value=versions;total.value=page.total;if(!from.value&&page.items[0])from.value=page.items[0].id}catch(e){if(seq===request)error.value=messageOf(e)}finally{if(seq===request)loading.value=false}}
async function selectProject(event:Event){const value=(event.target as HTMLSelectElement).value;if(!canLeave()){(event.target as HTMLSelectElement).value=project.value;return}project.value=value;detailRequest++;detail.value=undefined;comparison.value=undefined;from.value='';to.value='current';offset.value=0;await load()}
async function show(id:string){if(creating.value&&!canLeave())return;creating.value=false;const seq=++detailRequest;error.value='';try{const value=await api<PlanVersion>(`/api/plan-versions/${encodeURIComponent(id)}`);if(seq!==detailRequest)return;if(project.value!==value.project_id){project.value=value.project_id;offset.value=0;await load()}detail.value=value;from.value=value.id;comparison.value=undefined}catch(e){if(seq===detailRequest)error.value=messageOf(e)}}
async function refreshProjectVersion(){const latest=await api<Project>(`/api/projects/${project.value}`);projectVersion.value=latest.version;planStale.value=false}
async function reloadPlan(){saving.value=true;try{await refreshProjectVersion();error.value='已重新读取当前项目版本，请核对变化后再确认保存。'}catch(e){error.value=messageOf(e)}finally{saving.value=false}}
async function create(){if(!project.value||isProjectReadOnly(project.value)||!canLeave())return;saving.value=true;error.value='';try{await refreshProjectVersion();form.name='';form.description='';creating.value=true;await draft.reset()}catch(e){error.value=messageOf(e)}finally{saving.value=false}}
async function save(){if(saving.value||!project.value||!form.name.trim()||isProjectReadOnly(project.value))return;saving.value=true;error.value='';try{const saved=await api<PlanVersion>(`/api/projects/${project.value}/plan-versions`,{method:'POST',body:JSON.stringify({...form,project_version:projectVersion.value})});draft.discard();creating.value=false;offset.value=0;await load();await show(saved.id);notify('计划版本已保存，历史快照不会随当前任务修改');emit('changed')}catch(e){error.value=messageOf(e);if(e instanceof ApiError&&e.status===409){planStale.value=true;error.value+='。项目计划已变化；请核对后重新读取当前计划，再确认保存。'}draft.persist()}finally{saving.value=false}}
async function compare(){if(!project.value||!from.value||!to.value)return;comparing.value=true;error.value='';const pid=project.value;try{const result=await api<PlanComparison>(`/api/projects/${pid}/plan-versions/compare?${query({from:from.value,to:to.value})}`);if(project.value===pid)comparison.value=result}catch(e){error.value=messageOf(e)}finally{comparing.value=false}}
async function exportComparison(format:ExportFormat){const value=comparison.value;if(!value||exporting.value||comparing.value)return;exporting.value=true;error.value='';try{const job=await api<ExportJob>(`/api/projects/${encodeURIComponent(value.project_id)}/plan-versions/compare-export`,{method:'POST',body:JSON.stringify({from:value.from.id,to:value.to.current?'current':value.to.id,from_hash:value.from.hash,to_hash:value.to.hash,format,...(format==='docx'?{template_id:builtinTemplate('plan_comparisons')}:{})})});notify('已固定比较两端快照并创建导出任务');location.hash=`#/exports?job=${encodeURIComponent(job.id)}`}catch(e){error.value=messageOf(e)}finally{exporting.value=false}}
async function exportSaved(print=false){if(!detail.value||exporting.value)return;exporting.value=true;try{if(print)await queuePrintExport('plan_versions',detail.value);else await queueWordExport('plan_versions',detail.value)}catch(e){error.value=messageOf(e)}finally{exporting.value=false}}
function close(){if(!saving.value&&draft.canLeave())creating.value=false}
onMounted(()=>{project.value=ui.projects[0]?.id||'';void load()});watch(()=>props.revision,()=>void load())
defineExpose({canLeave,openEntity:show})
</script>
<template>
<div class="page-heading"><div><h1>任务与 WBS</h1><p class="page-description">给完整项目计划留一个固定版本，再核对之后的变化。</p></div><button class="button primary" :disabled="saving||!project||isProjectReadOnly(project)" @click="create"><Plus :size="16"/>保存计划版本</button></div><TaskTabs active="plans"/>
<div class="filter-bar"><select :value="project" aria-label="计划版本所属项目" @change="selectProject"><option value="" disabled>选择项目</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><p class="input-hint">保存整个项目的WBS快照。旧版本只读，不会应用或覆盖当前任务。</p></div>
<div v-if="error" class="error-banner" role="alert">{{error}}</div>
<div class="worklog-layout plan-layout"><aside class="surface saved-logs"><div class="section-heading"><h2>计划版本 <span class="count">{{total}}</span></h2></div><p v-if="loading" class="loading-message">正在读取版本…</p><div v-else-if="!items.length" class="empty-state compact"><ShieldCheck :size="30"/><p>{{project?'还没有保存版本。确认当前WBS后，保存一份计划快照。':'先建立并选择一个项目。'}}</p></div><div v-else class="log-list"><button v-for="item in items" :key="item.id" :class="{selected:detail?.id===item.id}" @click="show(item.id)"><strong>{{item.number}} · {{item.name}}</strong><span>{{item.task_count}} 项任务 · {{dateTimeLabel(item.created_at)}}</span></button></div><Pager :offset="offset" :limit="limit" :total="total" @change="offset=$event;load()"/></aside>
<section class="surface plan-detail"><template v-if="detail"><div class="section-heading"><div><h2>{{detail.number}} · {{detail.name}}</h2><p class="input-hint">{{detail.created_by}} · {{dateTimeLabel(detail.created_at)}} · {{detail.task_count}} 项任务</p></div><div class="row-actions"><a class="button subtle small" :href="`/api/plan-versions/${encodeURIComponent(detail.id)}/download`" download><Download :size="14"/>JSON</a><button class="button subtle small" :disabled="exporting" @click="exportSaved()">导出 Word</button><button class="button subtle small" :disabled="exporting" @click="exportSaved(true)">打印 / PDF</button></div></div><div v-if="detail.snapshot?.project" class="plan-project-metadata"><span>项目：{{detail.snapshot.project.name||projectName(detail.project_id)}}</span><span>开始：{{detail.snapshot.project.start_date||'未设置'}}</span><span>结束：{{detail.snapshot.project.end_date||'未设置'}}</span><span>负责人：{{detail.snapshot.project.manager||'未指定'}}</span></div><p v-if="detail.description" class="plan-description">{{detail.description}}</p><details class="plan-hash"><summary>快照SHA-256</summary><code>{{detail.hash}}</code></details><div class="table-scroll"><table class="snapshot-task-table"><thead><tr><th>WBS / 任务</th><th>负责人</th><th>计划开始</th><th>计划结束</th><th class="right">预计工时</th></tr></thead><tbody><tr v-for="task in detail.snapshot?.tasks||[]" :key="task.id"><td><div :style="{paddingLeft:`${(task.depth||0)*18}px`}"><span class="muted">{{task.wbs_code}}</span> {{task.name}}<details v-if="task.description" class="snapshot-description"><summary>说明</summary><p>{{task.description}}</p></details></div></td><td>{{task.assignee||'未指定'}}</td><td>{{task.plan_start||'未设置'}}</td><td>{{task.plan_end||'未设置'}}</td><td class="right">{{task.estimate_hours}} 小时</td></tr></tbody></table></div><p v-if="!detail.snapshot?.tasks?.length" class="empty-state compact">此版本没有任务。</p></template><div v-else class="empty-state editor-empty"><ShieldCheck :size="36"/><h2>查看固定的计划快照</h2><p>从左侧选择一个版本，或保存当前项目计划。</p></div></section></div>
<section v-if="choices.length" class="surface plan-compare"><div class="section-heading"><h2><GitCompareArrows :size="17"/>比较计划变化</h2></div><form class="filter-bar" @submit.prevent="compare"><label>从版本<select v-model="from" required><option v-for="item in choices" :key="item.id" :value="item.id">{{item.number}} · {{item.name}}</option></select></label><label>到版本<select v-model="to" required><option value="current">当前任务计划</option><option v-for="item in choices" :key="item.id" :value="item.id">{{item.number}} · {{item.name}}</option></select></label><button class="button primary small" :disabled="comparing||!from">{{comparing?'正在比较…':'比较'}}</button></form><template v-if="comparison"><div class="comparison-export"><div><strong>{{comparison.from.name}} → {{comparison.to.current?'当前任务计划':comparison.to.name}}</strong><p class="input-hint">导出使用本次比较的两端快照。当前计划已变化时，请重新比较后导出。</p></div><ExportFormatPicker :busy="exporting" :disabled="comparing" label="计划比较导出格式" @export="exportComparison"/></div><p class="compare-summary">新增 {{comparison.summary.added}} · 删除 {{comparison.summary.removed}} · 修改 {{comparison.summary.changed}} · 移动 {{comparison.summary.moved}} · 调序 {{comparison.summary.reordered}}</p><div v-for="group in changeGroups" :key="group.label" class="change-group"><h3>{{group.label}}任务（{{group.tasks.length}}）</h3><ul><li v-for="task in group.tasks" :key="task.id">{{task.wbs_code}} {{task.name}}</li></ul></div><div v-for="item in comparison.changed" :key="item.id" class="change-group"><h3>{{item.after.wbs_code}} {{item.after.name}} <span class="muted">{{item.moved?'上级改变':''}} {{item.reordered?'顺序改变':''}}</span></h3><div class="table-scroll"><table><thead><tr><th>字段</th><th>原计划</th><th>新计划</th></tr></thead><tbody><tr v-for="field in item.fields" :key="field.field"><td>{{planningLabels[field.field]||field.field}}</td><td class="compare-value">{{planningValue(field.before)}}</td><td class="compare-value">{{planningValue(field.after)}}</td></tr></tbody></table></div></div><p v-if="!comparison.summary.total" class="empty-state compact">两个计划没有任务差异。</p></template></section>
<Modal :open="creating" title="保存完整项目计划" @close="close"><form class="modal-body" @submit.prevent="save"><DraftNotice :value="draft.available.value" :values="draft.values.value" :error="draft.storageError.value" :recovery="draft.recovery.value" @select="draft.select" @restore="draft.restore" @force="draft.restoreForced" @cancel-recovery="draft.clearRecovery" @discard="draft.discardAvailable"/><p class="input-hint">{{currentProject?.name}} · 保存此刻整个项目的任务层级和计划字段，不受当前任务列表筛选影响。</p><div v-if="error" class="error-banner" role="alert">{{error}}<button v-if="planStale" type="button" class="text-button" :disabled="saving" @click="reloadPlan">重新读取当前计划</button></div><fieldset :disabled="saving"><label>版本名称 <span class="required">*</span><input v-model="form.name" required maxlength="200" autofocus placeholder="如：联调前确认计划"/></label><label>说明<textarea v-model="form.description" rows="4" maxlength="2000" placeholder="记录保存版本的背景或本次调整范围"/></label></fieldset><div class="modal-footer"><button class="button primary" :disabled="saving||planStale">{{saving?'正在保存…':'确认保存版本'}}</button></div></form></Modal>
</template>
<style scoped>.log-list button{display:flex;flex-direction:column;align-items:flex-start;gap:5px;text-align:left}.log-list strong{font-size:13px;line-height:1.7;overflow-wrap:anywhere}.log-list button>span{font-size:11px;line-height:1.6;overflow-wrap:anywhere}.plan-project-metadata{display:flex;flex-wrap:wrap;gap:8px 20px;padding:16px 20px 0;font-size:12px;color:var(--muted)}.plan-layout{align-items:start}.plan-detail .section-heading{align-items:flex-start}.plan-detail .row-actions{flex-wrap:wrap;justify-content:flex-end}.plan-description{padding:16px 20px;white-space:pre-wrap;line-height:1.8}.plan-hash{padding:0 20px 16px;font-size:12px;color:var(--muted)}.plan-hash code{display:block;overflow-wrap:anywhere;margin-top:8px}.snapshot-description{font-size:11px;margin-top:5px;color:var(--muted)}.snapshot-description p{white-space:pre-wrap;line-height:1.8;max-width:60ch}.snapshot-task-table{min-width:680px}.snapshot-task-table th:first-child{min-width:260px}.plan-compare{margin-top:24px}.plan-compare>.filter-bar{padding:18px 20px;margin:0;align-items:flex-end}.plan-compare label{margin:0;display:flex;flex-direction:column;gap:6px}.comparison-export{display:flex;align-items:flex-start;justify-content:space-between;gap:16px;flex-wrap:wrap;padding:0 20px 16px}.comparison-export strong{font-size:13px}.comparison-export .input-hint{margin-top:6px}.compare-summary{padding:0 20px 16px;font-size:13px;color:var(--muted)}.change-group{padding:16px 20px;border-top:1px solid var(--border)}.change-group h3{margin-bottom:12px}.change-group ul{margin:0;padding-left:20px;line-height:1.9}.compare-value{white-space:pre-wrap;overflow-wrap:anywhere;min-width:150px}@media(max-width:700px){.plan-detail .section-heading{flex-direction:column;gap:12px}.plan-detail .row-actions{justify-content:flex-start}}</style>
